+      const digitsOnly = value.replace(/\D/g, "");
+      const plusCount = (value.match(/\+/g) || []).length;
+      const looksValid = allowedCharacters.test(value) && digitsOnly.length >= 7 && digitsOnly.length <= 15 && plusCount <= 1;
+
+      if (!looksValid) {
+        if (showError) {
+          setFieldError(field, field.message, [helpId, "phone-number-error"]);
+        }
+        return false;
+      }
+
+      clearFieldError(field, [helpId]);
+      return true;
+    }
+
+    function validateForm(showError) {
+      const firstInvalid = [];
+
+      if (!validateFullName(showError)) firstInvalid.push(fields.fullName.input);
+      if (!validateEmail(showError)) firstInvalid.push(fields.emailAddress.input);
+      if (!validatePhone(showError)) firstInvalid.push(fields.phoneNumber.input);
+
+      return { valid: firstInvalid.length === 0, firstInvalid };
+    }
+
+    Object.values(fields).forEach((field) => {
+      field.input.addEventListener("input", () => {
+        if (field.input === fields.fullName.input) {
+          validateFullName(true);
+        } else if (field.input === fields.emailAddress.input) {
+          validateEmail(true);
+        } else {
+          validatePhone(true);
+        }
+
+        if (form.dataset.submitted === "true") {
+          const result = validateForm(true);
+          status.textContent = result.valid ? "All fields look good." : "Please fix the highlighted fields.";
+          status.dataset.state = result.valid ? "success" : "error";
+        } else {
+          status.textContent = "";
+          status.removeAttribute("data-state");
+        }
+      });
+
+      field.input.addEventListener("blur", () => {
+        if (field.input === fields.fullName.input) {
+          validateFullName(true);
+        } else if (field.input === fields.emailAddress.input) {
+          validateEmail(true);
+        } else {
+          validatePhone(true);
+        }
+      });
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      form.dataset.submitted = "true";
+
+      const result = validateForm(true);
+
+      if (!result.valid) {
+        status.textContent = "Please fix the highlighted fields.";
+        status.dataset.state = "error";
+        result.firstInvalid[0].focus();
+        return;
+      }
+
+      status.textContent = "All fields look good.";
+      status.dataset.state = "success";
+    });
+  </script>
+</body>
