      const value = field.input.value.trim();

      if (!value) {
        if (showError) {
          setFieldError(field, field.message, ["full-name-error"]);
        }
        return false;
      }

      clearFieldError(field, []);
      return true;
    }

    function validateEmail(showError) {
      const field = fields.emailAddress;

      if (!field.input.value.trim() || !field.input.checkValidity()) {
        if (showError) {
          setFieldError(field, field.message, ["email-address-error"]);
        }
        return false;
      }

      clearFieldError(field, []);
      return true;
    }

    function validatePhone(showError) {
      const field = fields.phoneNumber;
      const value = field.input.value.trim();
      const helpId = "phone-number-help";

      if (!value) {
        clearFieldError(field, [helpId]);
        return true;
      }

      const allowedCharacters = /^[0-9()+.\-\s]+$/;
      const digitsOnly = value.replace(/\D/g, "");
      const plusCount = (value.match(/\+/g) || []).length;
      const looksValid = allowedCharacters.test(value) && digitsOnly.length >= 7 && digitsOnly.length <= 15 && plusCount <= 1;

      if (!looksValid) {
        if (showError) {
          setFieldError(field, field.message, [helpId, "phone-number-error"]);
        }
        return false;
      }

      clearFieldError(field, [helpId]);
      return true;
    }

