388.     const form = document.getElementById("support-form");
389.     const status = document.getElementById("form-status");
390. 
391.     const fields = {
392.       fullName: {
393.         input: document.getElementById("full-name"),
394.         error: document.getElementById("full-name-error"),
395.         message: "Error: Enter your full name."
396.       },
397.       emailAddress: {
398.         input: document.getElementById("email-address"),
399.         error: document.getElementById("email-address-error"),
400.         message: "Error: Enter a valid email address, such as name@example.com."
401.       },
402.       phoneNumber: {
403.         input: document.getElementById("phone-number"),
404.         error: document.getElementById("phone-number-error"),
405.         message: "Error: Enter a phone number using the format shown in the helper text."
406.       }
407.     };
408. 
409.     function setFieldError(field, message, describedByIds) {
410.       field.input.setAttribute("aria-invalid", "true");
411.       field.error.textContent = message;
412.       field.error.hidden = false;
413.       field.input.setAttribute("aria-describedby", describedByIds.join(" "));
414.     }
415. 
416.     function clearFieldError(field, describedByIds) {
417.       field.input.removeAttribute("aria-invalid");
418.       field.error.hidden = true;
419.       field.error.textContent = "";
420. 
421.       if (describedByIds.length) {
422.         field.input.setAttribute("aria-describedby", describedByIds.join(" "));
423.       } else {
424.         field.input.removeAttribute("aria-describedby");
425.       }
426.     }
427. 
428.     function validateFullName(showError) {
429.       const field = fields.fullName;
430.       const value = field.input.value.trim();
431. 
432.       if (!value) {
433.         if (showError) {
434.           setFieldError(field, field.message, ["full-name-error"]);
435.         }
436.         return false;
437.       }
438. 
439.       clearFieldError(field, []);
440.       return true;
441.     }
442. 
443.     function validateEmail(showError) {
444.       const field = fields.emailAddress;
445. 
446.       if (!field.input.value.trim() || !field.input.checkValidity()) {
447.         if (showError) {
448.           setFieldError(field, field.message, ["email-address-error"]);
449.         }
450.         return false;
451.       }
452. 
453.       clearFieldError(field, []);
454.       return true;
455.     }
456. 
457.     function validatePhone(showError) {
458.       const field = fields.phoneNumber;
459.       const value = field.input.value.trim();
460.       const helpId = "phone-number-help";
461. 
462.       if (!value) {
463.         clearFieldError(field, [helpId]);
464.         return true;
465.       }
466. 
467.       const allowedCharacters = /^[0-9()+.\-\s]+$/;
468.       const digitsOnly = value.replace(/\D/g, "");
469.       const plusCount = (value.match(/\+/g) || []).length;
470.       const looksValid = allowedCharacters.test(value) && digitsOnly.length >= 7 && digitsOnly.length <= 15 && plusCount <= 1;
471. 
472.       if (!looksValid) {
473.         if (showError) {
474.           setFieldError(field, field.message, [helpId, "phone-number-error"]);
475.         }
476.         return false;
477.       }
478. 
479.       clearFieldError(field, [helpId]);
480.       return true;
481.     }
482. 
483.     function validateForm(showError) {
484.       const firstInvalid = [];
485. 
486.       if (!validateFullName(showError)) firstInvalid.push(fields.fullName.input);
487.       if (!validateEmail(showError)) firstInvalid.push(fields.emailAddress.input);
488.       if (!validatePhone(showError)) firstInvalid.push(fields.phoneNumber.input);
489. 
490.       return { valid: firstInvalid.length === 0, firstInvalid };
491.     }
492. 
493.     Object.values(fields).forEach((field) => {
494.       field.input.addEventListener("input", () => {
495.         if (field.input === fields.fullName.input) {
496.           validateFullName(true);
497.         } else if (field.input === fields.emailAddress.input) {
498.           validateEmail(true);
499.         } else {
500.           validatePhone(true);
501.         }
502. 
503.         if (form.dataset.submitted === "true") {
504.           const result = validateForm(true);
505.           status.textContent = result.valid ? "All fields look good." : "Please fix the highlighted fields.";
506.           status.dataset.state = result.valid ? "success" : "error";
507.         } else {
508.           status.textContent = "";
509.           status.removeAttribute("data-state");
510.         }
511.       });
512. 
