514.         if (field.input === fields.fullName.input) {
515.           validateFullName(true);
516.         } else if (field.input === fields.emailAddress.input) {
517.           validateEmail(true);
518.         } else {
519.           validatePhone(true);
520.         }
521.       });
522.     });
523. 
