  <a class="skip-link" href="#support-form">Skip to support form</a>

  <main id="main-content">
    <div class="page-shell">
      <section class="hero" aria-labelledby="support-heading">
        <p class="eyebrow">Support</p>
        <h1 id="support-heading">Contact our team</h1>
        <p>Send a quick message and we&apos;ll route it to the right person. Required fields are marked with an asterisk.</p>
        <ul class="hero-list" aria-label="What to include">
          <li>Use your full name and email address so we can reply promptly.</li>
          <li>Phone number is optional if you&apos;d like a call back.</li>
          <li>Inline validation helps you fix issues before sending.</li>
        </ul>
      </section>

      <section class="form-card" aria-labelledby="support-form-heading">
        <h2 id="support-form-heading">Support contact form</h2>
        <p class="form-note"><span aria-hidden="true">*</span> Required fields</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              class="field-input"
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
            >
            <p class="field-error" id="full-name-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
