    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--accent);
      outline-offset: 2px;
    }

    main {
      width: min(100%, 72rem);
      margin: 0 auto;
      padding: 5rem 1rem 3rem;
    }

    .page-shell {
      display: grid;
      gap: 1.5rem;
      grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
      align-items: start;
    }

    .hero,
    .form-card {
      background: var(--surface);
      border: 1px solid rgba(148, 163, 184, 0.30);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
    }

    .hero {
      padding: 2rem;
      background:
        linear-gradient(180deg, rgba(37, 99, 235, 0.06), rgba(37, 99, 235, 0.02)),
        var(--surface);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      margin: 0 0 1rem;
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      background: rgba(37, 99, 235, 0.08);
      color: var(--accent-strong);
      font-size: 0.875rem;
      font-weight: 650;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.05;
      letter-spacing: -0.03em;
    }

    .hero p {
      margin: 1rem 0 0;
      max-width: 54ch;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .hero-list {
      display: grid;
      gap: 0.75rem;
      margin: 1.5rem 0 0;
      padding: 0;
      list-style: none;
      color: var(--muted);
    }

    .hero-list li {
      display: flex;
      gap: 0.75rem;
      align-items: flex-start;
    }

    .hero-list li::before {
      content: "";
      flex: 0 0 auto;
      width: 0.75rem;
      height: 0.75rem;
      margin-top: 0.4rem;
      border-radius: 999px;
      background: linear-gradient(180deg, var(--accent), var(--accent-strong));
    }

    .form-card {
      padding: 1.5rem;
    }

    .form-note {
      margin: 0 0 1.5rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    label {
      font-weight: 600;
      line-height: 1.25;
    }

    .required-mark {
      color: var(--error);
      margin-left: 0.15rem;
    }

    .field-input {
      width: 100%;
      padding: 0.95rem 1rem;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface-alt);
      color: var(--text);
      font: inherit;
      transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
    }

    .field-input::placeholder {
      color: #8a96a8;
    }

    .field-input:hover {
      border-color: var(--border-strong);
    }

    .field-input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: var(--focus);
      background: #fff;
    }

    .field-help,
    .field-error {
      margin: 0;
      font-size: 0.92rem;
    }

    .field-help {
      color: var(--muted);
    }

    .field-error {
      color: var(--error);
      background: var(--error-bg);
      border-radius: 12px;
      padding: 0.55rem 0.75rem;
    }

    .field-error[hidden] {
      display: none;
    }

    .field-input[aria-invalid="true"] {
      border-color: var(--error);
      box-shadow: 0 0 0 3px rgba(185, 28, 28, 0.12);
      background: #fff;
    }

    .submit-row {
      display: grid;
      gap: 0.75rem;
      margin-top: 0.25rem;
    }

    .button {
      appearance: none;
      border: 0;
      border-radius: 14px;
      padding: 0.95rem 1.25rem;
      background: linear-gradient(180deg, var(--accent), var(--accent-strong));
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 16px 30px rgba(37, 99, 235, 0.25);
    }

    .button:hover {
      filter: brightness(1.02);
    }

    .button:focus-visible {
      outline: 3px solid #fff;
      box-shadow: 0 0 0 3px var(--accent-strong), 0 16px 30px rgba(37, 99, 235, 0.25);
    }

    .form-status {
      margin: 0;
      min-height: 1.5em;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .form-status[data-state="error"] {
      color: var(--error);
    }

    .form-status[data-state="success"] {
      color: #166534;
    }

    @media (max-width: 840px) {
      main {
        padding-top: 4rem;
      }

      .page-shell {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 520px) {
      main {
        padding-inline: 0.75rem;
      }

      .hero,
      .form-card {
        padding: 1.25rem;
        border-radius: 18px;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
      .hero,
      .form-card,
      .field-input,
      .button,
      .field-error {
        forced-color-adjust: auto;
      }

      .field-input:focus,
      .button:focus-visible,
      .skip-link:focus {
        outline: 2px solid Highlight;
        outline-offset: 2px;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#support-form">Skip to support form</a>

  <main id="main-content">
    <div class="page-shell">
      <section class="hero" aria-labelledby="support-heading">
        <p class="eyebrow">Support</p>
        <h1 id="support-heading">Contact our team</h1>
        <p>Send a quick message and we&apos;ll route it to the right person. Required fields are marked with an asterisk.</p>
        <ul class="hero-list" aria-label="What to include">
          <li>Use your full name and email address so we can reply promptly.</li>
          <li>Phone number is optional if you&apos;d like a call back.</li>
          <li>Inline validation helps you fix issues before sending.</li>
        </ul>
      </section>

      <section class="form-card" aria-labelledby="support-form-heading">
        <h2 id="support-form-heading">Support contact form</h2>
        <p class="form-note"><span aria-hidden="true">*</span> Required fields</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              class="field-input"
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
            >
            <p class="field-error" id="full-name-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              class="field-input"
              id="email-address"
              name="emailAddress"
              type="email"
              autocomplete="email"
              required
              inputmode="email"
            >
            <p class="field-error" id="email-address-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
            <input
              class="field-input"
              id="phone-number"
              name="phoneNumber"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-number-help"
            >
            <p class="field-help" id="phone-number-help">Optional. Use digits, spaces, dashes, parentheses, or a leading +. Example: +1 555-123-4567.</p>
            <p class="field-error" id="phone-number-error" hidden></p>
          </div>

          <div class="submit-row">
            <button class="button" type="submit">Send message</button>
            <p class="form-status" id="form-status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const status = document.getElementById("form-status");

    const fields = {
      fullName: {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        message: "Error: Enter your full name.",
        baseDescribedBy: []
      },
      emailAddress: {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        message: "Error: Enter a valid email address, such as name@example.com.",
        baseDescribedBy: []
      },
      phoneNumber: {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        message: "Error: Enter a phone number using the format shown in the helper text.",
        baseDescribedBy: ["phone-number-help"]
      }
    };

    function setDescribedBy(field, extraIds = []) {
      const ids = [...new Set([...field.baseDescribedBy, ...extraIds].filter(Boolean))];

      if (ids.length) {
        field.input.setAttribute("aria-describedby", ids.join(" "));
      } else {
        field.input.removeAttribute("aria-describedby");
      }
    }

    function setFieldError(field, message, describedByIds) {
      field.input.setAttribute("aria-invalid", "true");
      field.error.textContent = message;
      field.error.hidden = false;
      setDescribedBy(field, describedByIds);
    }

    function clearFieldError(field) {
      field.input.removeAttribute("aria-invalid");
      field.error.hidden = true;
      field.error.textContent = "";
      setDescribedBy(field);
    }

    function validateFullName(showError) {
      const field = fields.fullName;
      const value = field.input.value.trim();

      if (!value) {
        if (showError) {
          setFieldError(field, field.message, ["full-name-error"]);
        }
        return false;
      }

      clearFieldError(field);
      return true;
    }

    function validateEmail(showError) {
      const field = fields.emailAddress;

      if (!field.input.value.trim() || !field.input.checkValidity()) {
        if (showError) {
          setFieldError(field, field.message, ["email-address-error"]);
        }
        return false;
      }

      clearFieldError(field);
      return true;
    }

    function validatePhone(showError) {
      const field = fields.phoneNumber;
      const value = field.input.value.trim();
      const helpId = "phone-number-help";

      if (!value) {
        clearFieldError(field);
        return true;
      }

      const allowedCharacters = /^[0-9()+.\-\s]+$/;
      const digitsOnly = value.replace(/\D/g, "");
      const plusCount = (value.match(/\+/g) || []).length;
      const looksValid = allowedCharacters.test(value) && digitsOnly.length >= 7 && digitsOnly.length <= 15 && plusCount <= 1;

      if (!looksValid) {
        if (showError) {
          setFieldError(field, field.message, [helpId, "phone-number-error"]);
        }
        return false;
      }

      clearFieldError(field);
      return true;
    }

    function validateForm(showError) {
      const firstInvalid = [];

      if (!validateFullName(showError)) firstInvalid.push(fields.fullName.input);
      if (!validateEmail(showError)) firstInvalid.push(fields.emailAddress.input);
      if (!validatePhone(showError)) firstInvalid.push(fields.phoneNumber.input);

      return { valid: firstInvalid.length === 0, firstInvalid };
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        if (field.input === fields.fullName.input) {
          validateFullName(true);
        } else if (field.input === fields.emailAddress.input) {
          validateEmail(true);
        } else {
          validatePhone(true);
        }

        if (form.dataset.submitted === "true") {
          const result = validateForm(true);
          status.textContent = result.valid ? "All fields look good." : "Please fix the highlighted fields.";
          status.dataset.state = result.valid ? "success" : "error";
        } else {
          status.textContent = "";
          status.removeAttribute("data-state");
        }
      });

      field.input.addEventListener("blur", () => {
        if (field.input === fields.fullName.input) {
          validateFullName(true);
        } else if (field.input === fields.emailAddress.input) {
          validateEmail(true);
        } else {
          validatePhone(true);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      form.dataset.submitted = "true";

      const result = validateForm(true);

      if (!result.valid) {
        status.textContent = "Please fix the highlighted fields.";
        status.dataset.state = "error";
        result.firstInvalid[0].focus();
        return;
      }

      status.textContent = "All fields look good.";
      status.dataset.state = "success";
    });
  </script>
</body>
</html>
