       if (ids.length) {
         field.input.setAttribute("aria-describedby", ids.join(" "));
       } else {
         field.input.removeAttribute("aria-describedby");
       }
     }

     function setFieldError(field, message, describedByIds) {
       field.input.setAttribute("aria-invalid", "true");
       field.error.textContent = message;
       field.error.hidden = false;
       setDescribedBy(field, describedByIds);
     }

     function clearFieldError(field) {
       field.input.removeAttribute("aria-invalid");
       field.error.hidden = true;
       field.error.textContent = "";
       setDescribedBy(field);
     }

     function validateFullName(showError) {
       const field = fields.fullName;
       const value = field.input.value.trim();

       if (!value) {
         if (showError) {
           setFieldError(field, field.message, ["full-name-error"]);
         }
         return false;
       }

       clearFieldError(field);
       return true;
     }

     function validateEmail(showError) {
       const field = fields.emailAddress;

       if (!field.input.value.trim() || !field.input.checkValidity()) {
         if (showError) {
           setFieldError(field, field.message, ["email-address-error"]);
         }
         return false;
       }

       clearFieldError(field);
       return true;
     }

     function validatePhone(showError) {
       const field = fields.phoneNumber;
       const value = field.input.value.trim();
       const helpId = "phone-number-help";

       if (!value) {
         clearFieldError(field);
         return true;
       }

       const allowedCharacters = /^[0-9()+.\-\s]+$/;
       const digitsOnly = value.replace(/\D/g, "");
       const plusCount = (value.match(/\+/g) || []).length;
       const looksValid = allowedCharacters.test(value) && digitsOnly.length >= 7 && digitsOnly.length <= 15 && plusCount <= 1;

       if (!looksValid) {
         if (showError) {
           setFieldError(field, field.message, [helpId, "phone-number-error"]);
         }
         return false;
       }

       clearFieldError(field);
       return true;
     }

     function validateForm(showError) {
       const firstInvalid = [];

       if (!validateFullName(showError)) firstInvalid.push(fields.fullName.input);
       if (!validateEmail(showError)) firstInvalid.push(fields.emailAddress.input);
       if (!validatePhone(showError)) firstInvalid.push(fields.phoneNumber.input);

       return { valid: firstInvalid.length === 0, firstInvalid };
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener("input", () => {
         if (field.input === fields.fullName.input) {
           validateFullName(true);
         } else if (field.input === fields.emailAddress.input) {
           validateEmail(true);
         } else {
           validatePhone(true);
         }

         if (form.dataset.submitted === "true") {
           const result = validateForm(true);
           status.textContent = result.valid ? "All fields look good." : "Please fix the highlighted fields.";
           status.dataset.state = result.valid ? "success" : "error";
         } else {
           status.textContent = "";
           status.removeAttribute("data-state");
         }
       });

